*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--ink);
  background: var(--bg);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
ul { list-style: none; padding: 0; margin: 0; }

:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --soft: #f1efe9;
  --ink: #14130f;
  --ink-2: #45433d;
  --muted: #87857d;
  --line: #e7e4dc;
  --accent: #b8553d;
  --accent-ink: #7a3424;
  --gold: #c8a96a;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(20,19,15,.04), 0 1px 1px rgba(20,19,15,.03);
  --shadow-md: 0 8px 24px rgba(20,19,15,.06), 0 2px 6px rgba(20,19,15,.04);
  --shadow-lg: 0 24px 60px rgba(20,19,15,.12);
  --maxw: 1240px;
}

.container { max-width: var(--maxw); margin: 0 auto; padding: 0 24px; }

.visually-hidden {
  position: absolute !important; width: 1px; height: 1px; padding: 0;
  margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

/* ---------- Typography ---------- */
h1, h2, h3 { font-family: 'Fraunces', Georgia, serif; font-weight: 600; letter-spacing: -0.01em; color: var(--ink); margin: 0; }
h1 { font-size: clamp(2.4rem, 5vw, 4.2rem); line-height: 1.05; }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); line-height: 1.15; }
h3 { font-size: 1.2rem; line-height: 1.3; }
.eyebrow {
  font-size: .72rem; letter-spacing: .14em; text-transform: uppercase;
  font-weight: 600; color: var(--muted); margin: 0 0 12px;
}
.eyebrow--light { color: rgba(255,255,255,.75); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px; padding: 14px 22px; border-radius: 999px;
  font-weight: 600; font-size: .92rem; transition: transform .15s ease, background .2s ease, color .2s ease;
  border: 1px solid transparent;
}
.btn--primary { background: var(--ink); color: #fff; }
.btn--primary:hover { background: #2a2722; transform: translateY(-1px); }
.btn--ghost { background: transparent; color: var(--ink); border-color: var(--line); }
.btn--ghost:hover { background: var(--soft); }

.icon-btn {
  width: 40px; height: 40px; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%; color: var(--ink); position: relative; transition: background .15s ease;
}
.icon-btn:hover { background: var(--soft); }
.icon-btn--cart .cart-count {
  position: absolute; top: 2px; right: 2px;
  background: var(--accent); color: #fff; font-size: .65rem; font-weight: 700;
  min-width: 18px; height: 18px; border-radius: 999px; padding: 0 5px;
  display: inline-flex; align-items: center; justify-content: center;
  transform: scale(0); transition: transform .2s cubic-bezier(.5,1.7,.4,1);
}
.icon-btn--cart .cart-count.is-visible { transform: scale(1); }

/* ---------- Announcement ---------- */
.announcement {
  background: var(--ink); color: #f4f2eb; font-size: .82rem;
  overflow: hidden; padding: 10px 0;
}
.announcement__track {
  display: flex; gap: 28px; justify-content: center; align-items: center;
  flex-wrap: wrap; padding: 0 24px;
}
.announcement strong { color: var(--gold); }

/* ---------- Header ---------- */
.header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250,250,247,.85); backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header__inner {
  display: grid; grid-template-columns: auto 1fr auto; align-items: center;
  gap: 24px; height: 70px;
}
.header__menu { display: none; }
.logo {
  font-family: 'Fraunces', serif; font-weight: 700; font-size: 1.45rem; letter-spacing: -.01em;
}
.logo span { color: var(--accent); font-style: italic; font-weight: 600; }
.logo--light { color: #fff; }

.nav { display: flex; gap: 28px; justify-self: center; }
.nav a {
  font-size: .92rem; font-weight: 500; color: var(--ink-2);
  position: relative; padding: 6px 0; transition: color .15s;
}
.nav a::after {
  content: ''; position: absolute; left: 0; bottom: 0; height: 1.5px; width: 0;
  background: var(--ink); transition: width .25s ease;
}
.nav a:hover { color: var(--ink); }
.nav a:hover::after { width: 100%; }
.nav__sale { color: var(--accent) !important; }

.header__actions { display: flex; gap: 4px; }

/* ---------- Hero ---------- */
.hero { padding: 56px 0 80px; }
.hero__grid {
  display: grid; grid-template-columns: 1.05fr 1fr; gap: 64px; align-items: center;
}
.hero__title { margin: 12px 0 20px; }
.hero__lede {
  font-size: 1.08rem; color: var(--ink-2); max-width: 480px; margin: 0 0 32px;
}
.hero__cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 40px; }
.hero__meta {
  display: flex; gap: 28px; flex-wrap: wrap;
  border-top: 1px solid var(--line); padding-top: 24px;
  font-size: .88rem; color: var(--muted);
}
.hero__meta strong { color: var(--ink); margin-right: 6px; }

.hero__visual {
  position: relative; aspect-ratio: 4/5; max-height: 620px;
}
.hero__image {
  position: absolute; border-radius: var(--radius-lg); overflow: hidden;
  background-size: cover; background-position: center; box-shadow: var(--shadow-md);
}
.hero__image--main {
  inset: 0;
  background-image: linear-gradient(160deg, #d6cdbd 0%, #a89d87 60%, #6b6557 100%);
}
.hero__image--main::after {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.35), transparent 50%),
    radial-gradient(circle at 75% 80%, rgba(20,19,15,.25), transparent 60%);
}
.hero__image--small {
  width: 42%; aspect-ratio: 1; right: -24px; bottom: -32px;
  background-image: linear-gradient(140deg, #b8553d 0%, #7a3424 100%);
  border: 6px solid var(--bg);
}
.hero__image--small::after {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,.25), transparent 55%);
}
.hero__badge {
  position: absolute; top: 24px; left: -32px;
  width: 110px; height: 110px; border-radius: 50%;
  background: var(--bg); color: var(--ink);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; box-shadow: var(--shadow-md); z-index: 2;
  animation: spin 24s linear infinite;
}
.hero__badge-num { font-family: 'Fraunces', serif; font-size: 2rem; font-weight: 700; line-height: 1; }
.hero__badge-text { font-size: .65rem; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-top: 4px; max-width: 70px; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Categories ---------- */
.categories { padding: 24px 0 64px; }
.categories__grid {
  display: grid; grid-template-columns: 1.4fr 1fr 1fr; gap: 16px;
  height: 380px;
}
.cat-card {
  position: relative; overflow: hidden; border-radius: var(--radius-lg);
  display: block; color: #fff;
  transition: transform .35s ease;
}
.cat-card:hover { transform: translateY(-3px); }
.cat-card--1 { background: linear-gradient(160deg, #c9b394 0%, #6b5639 100%); }
.cat-card--2 { background: linear-gradient(160deg, #4b5346 0%, #1f2620 100%); }
.cat-card--3 { background: linear-gradient(160deg, #c4a78a 0%, #7d5a3a 100%); }
.cat-card::before {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,255,255,.2), transparent 50%),
    radial-gradient(circle at 20% 80%, rgba(0,0,0,.3), transparent 60%);
}
.cat-card__overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.5) 0%, transparent 60%);
}
.cat-card__body {
  position: absolute; left: 28px; right: 28px; bottom: 28px; z-index: 2;
}
.cat-card__body h3 {
  font-size: clamp(1.4rem, 2vw, 2rem); color: #fff; margin: 4px 0 14px;
}
.cat-card__cta {
  font-size: .88rem; font-weight: 600; opacity: .9;
  border-bottom: 1px solid rgba(255,255,255,.4); padding-bottom: 4px;
  transition: opacity .2s, border-color .2s;
}
.cat-card:hover .cat-card__cta { opacity: 1; border-color: #fff; }

/* ---------- Sections ---------- */
.section { padding: 80px 0; }
.section--soft { background: var(--soft); }
.section__header {
  display: flex; align-items: end; justify-content: space-between;
  gap: 24px; margin-bottom: 40px; flex-wrap: wrap;
}
.section__title { max-width: 600px; }
.link-arrow { font-weight: 600; font-size: .92rem; color: var(--ink); }
.link-arrow:hover { color: var(--accent); }

/* ---------- Filters ---------- */
.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  padding: 9px 16px; border-radius: 999px; background: transparent;
  border: 1px solid var(--line); font-size: .85rem; font-weight: 500;
  color: var(--ink-2); transition: all .15s ease;
}
.chip:hover { border-color: var(--ink); color: var(--ink); }
.chip.is-active { background: var(--ink); border-color: var(--ink); color: #fff; }

/* ---------- Product Grid ---------- */
.product-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 28px 22px;
}
.product {
  background: transparent; border-radius: var(--radius);
  display: flex; flex-direction: column; gap: 12px;
  transition: transform .25s ease;
}
.product:hover { transform: translateY(-4px); }
.product__media {
  position: relative; aspect-ratio: 4/5; border-radius: var(--radius);
  overflow: hidden; background: var(--soft);
}
.product__img {
  position: absolute; inset: 0;
  background-size: cover; background-position: center;
  transition: transform .6s ease;
}
.product:hover .product__img { transform: scale(1.05); }
.product__tag {
  position: absolute; top: 12px; left: 12px; z-index: 2;
  background: #fff; color: var(--ink); font-size: .7rem; font-weight: 700;
  padding: 6px 10px; border-radius: 999px; letter-spacing: .04em;
}
.product__tag--sale { background: var(--accent); color: #fff; }
.product__tag--new { background: var(--ink); color: #fff; }
.product__wishlist {
  position: absolute; top: 10px; right: 10px; z-index: 2;
  width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,.9);
  color: var(--ink); display: flex; align-items: center; justify-content: center;
  transition: background .15s, color .15s;
}
.product__wishlist:hover, .product__wishlist.is-active { background: var(--accent); color: #fff; }
.product__add {
  position: absolute; left: 12px; right: 12px; bottom: 12px; z-index: 2;
  background: #fff; color: var(--ink); padding: 12px; border-radius: 10px;
  font-weight: 600; font-size: .85rem;
  opacity: 0; transform: translateY(8px);
  transition: opacity .25s, transform .25s, background .15s;
}
.product:hover .product__add, .product:focus-within .product__add { opacity: 1; transform: translateY(0); }
.product__add:hover { background: var(--ink); color: #fff; }
.product__info {
  display: flex; justify-content: space-between; align-items: start; gap: 12px; padding: 0 4px;
}
.product__name { font-size: .95rem; font-weight: 500; color: var(--ink); margin: 0; }
.product__cat { font-size: .78rem; color: var(--muted); margin: 2px 0 0; }
.product__price { font-size: .95rem; font-weight: 600; color: var(--ink); white-space: nowrap; text-align: right; }
.product__price s { color: var(--muted); font-weight: 400; margin-right: 6px; }

/* Product image gradient backgrounds */
.pimg-1 { background-image: linear-gradient(140deg, #e8dcc6 0%, #b8a481 100%); }
.pimg-2 { background-image: linear-gradient(140deg, #2c3530 0%, #6a7268 100%); }
.pimg-3 { background-image: linear-gradient(140deg, #d4b28c 0%, #8a6240 100%); }
.pimg-4 { background-image: linear-gradient(140deg, #f0e9dd 0%, #c4b89e 100%); }
.pimg-5 { background-image: linear-gradient(140deg, #b8553d 0%, #6a2f20 100%); }
.pimg-6 { background-image: linear-gradient(140deg, #4a4f55 0%, #1f2329 100%); }
.pimg-7 { background-image: linear-gradient(140deg, #e6d9c1 0%, #a08a66 100%); }
.pimg-8 { background-image: linear-gradient(140deg, #b59f7c 0%, #6b5535 100%); }
.pimg-1::after, .pimg-2::after, .pimg-3::after, .pimg-4::after,
.pimg-5::after, .pimg-6::after, .pimg-7::after, .pimg-8::after {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 30% 25%, rgba(255,255,255,.25), transparent 50%),
    radial-gradient(circle at 75% 80%, rgba(0,0,0,.2), transparent 60%);
}

/* ---------- Deals ---------- */
.countdown {
  display: flex; align-items: center; gap: 12px;
  font-size: .85rem; color: var(--ink-2);
}
.countdown__boxes { display: flex; gap: 6px; }
.countdown__boxes > div {
  background: #fff; border-radius: 10px; padding: 8px 12px;
  display: flex; flex-direction: column; align-items: center;
  min-width: 54px; box-shadow: var(--shadow-sm);
}
.countdown__boxes span {
  font-family: 'Fraunces', serif; font-size: 1.3rem; font-weight: 600;
  font-variant-numeric: tabular-nums; line-height: 1;
}
.countdown__boxes small {
  font-size: .65rem; text-transform: uppercase; letter-spacing: .1em;
  color: var(--muted); margin-top: 4px;
}

.deals-grid {
  display: grid; grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: 1fr 1fr; gap: 16px;
  height: 520px;
}
.deal {
  position: relative; overflow: hidden; border-radius: var(--radius-lg);
  display: block; color: #fff; transition: transform .35s ease;
}
.deal:hover { transform: translateY(-3px); }
.deal--feature { grid-row: span 2; }
.deal__image {
  position: absolute; inset: 0; background-size: cover; background-position: center;
}
.deal__image--1 { background-image: linear-gradient(160deg, #b8553d 0%, #4d2014 100%); }
.deal__image--2 { background-image: linear-gradient(160deg, #c8b89c 0%, #6a5a3e 100%); }
.deal__image--3 { background-image: linear-gradient(160deg, #3a4a48 0%, #182220 100%); }
.deal__image::after {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, rgba(255,255,255,.2), transparent 55%),
    linear-gradient(to top, rgba(0,0,0,.55) 0%, transparent 60%);
}
.deal__body {
  position: absolute; left: 24px; right: 24px; bottom: 24px; z-index: 2;
}
.deal--feature .deal__body { left: 36px; right: 36px; bottom: 36px; max-width: 420px; }
.deal__body h3 { color: #fff; font-size: 1.4rem; margin: 10px 0 8px; }
.deal--feature .deal__body h3 { font-size: clamp(1.6rem, 2.4vw, 2.2rem); margin: 12px 0 12px; }
.deal__body p { color: rgba(255,255,255,.85); font-size: .92rem; margin: 0 0 16px; max-width: 380px; }
.deal__cta {
  font-size: .88rem; font-weight: 600;
  border-bottom: 1px solid rgba(255,255,255,.4); padding-bottom: 4px;
  transition: border-color .2s;
}
.deal:hover .deal__cta { border-color: #fff; }
.tag {
  display: inline-block; background: rgba(255,255,255,.95); color: var(--ink);
  font-size: .7rem; font-weight: 700; padding: 6px 11px; border-radius: 999px;
  letter-spacing: .04em; text-transform: uppercase;
}
.tag--accent { background: var(--gold); color: var(--ink); }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 24px;
}
.story { display: flex; flex-direction: column; gap: 16px; }
.story--lead { grid-row: span 1; }
.story--lead .story__body h3 { font-size: clamp(1.4rem, 2.2vw, 1.9rem); }
.story__media {
  display: block; aspect-ratio: 16/10;
  border-radius: var(--radius); overflow: hidden;
  background-size: cover; background-position: center;
  transition: transform .35s ease;
}
.story:not(.story--lead) .story__media { aspect-ratio: 4/3; }
.story__media:hover { transform: scale(1.01); }
.story__media--1 { background: linear-gradient(135deg, #d6c5a5 0%, #6f5a3a 100%); }
.story__media--2 { background: linear-gradient(135deg, #e8e2d3 0%, #b3a888 100%); }
.story__media--3 { background: linear-gradient(135deg, #4a4035 0%, #1c1815 100%); }
.story__media--4 { background: linear-gradient(135deg, #97a39a 0%, #44514a 100%); }
.story__body h3 { margin: 4px 0 8px; line-height: 1.25; }
.story__body h3 a { color: var(--ink); transition: color .15s; }
.story__body h3 a:hover { color: var(--accent); }
.story__body p { color: var(--ink-2); margin: 0 0 12px; }
.story__meta { font-size: .82rem; color: var(--muted); display: flex; gap: 8px; }

/* ---------- Values ---------- */
.values { padding: 48px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.values__grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px;
}
.value h4 { margin: 14px 0 6px; font-size: 1rem; font-weight: 600; }
.value p { margin: 0; font-size: .88rem; color: var(--muted); }
.value svg { color: var(--ink); }

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--ink); color: #f4f2eb; padding: 80px 0;
}
.newsletter__inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center;
}
.newsletter h2 { color: #fff; margin: 0 0 12px; }
.newsletter__lede { color: rgba(244,242,235,.75); margin: 0; max-width: 440px; }
.newsletter__form {
  display: grid; grid-template-columns: 1fr auto; gap: 8px;
}
.newsletter__form input {
  padding: 16px 20px; border-radius: 999px; border: 1px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.06); color: #fff; font-size: 1rem; outline: none;
  transition: border-color .15s, background .15s;
}
.newsletter__form input::placeholder { color: rgba(255,255,255,.5); }
.newsletter__form input:focus { border-color: var(--gold); background: rgba(255,255,255,.1); }
.newsletter__form .btn--primary { background: var(--gold); color: var(--ink); }
.newsletter__form .btn--primary:hover { background: #d8b87a; }
.newsletter__note {
  grid-column: 1 / -1; font-size: .78rem; color: rgba(244,242,235,.55); margin: 4px 0 0;
}
.newsletter__note.is-success { color: var(--gold); }

/* ---------- Footer ---------- */
.footer {
  background: #0d0c0a; color: #c4c1b8; padding: 64px 0 24px;
}
.footer__grid {
  display: grid; grid-template-columns: 1.5fr 1fr 1fr 1fr; gap: 48px;
  margin-bottom: 48px;
}
.footer__brand p { color: #87857d; font-size: .9rem; max-width: 280px; margin: 16px 0 0; }
.footer h5 {
